for (const tabInfo of tabmail.tabInfo) {
  const tab = tabmail.getTabForBrowser(tabInfo.browser);
  if (tab?.urlbar?.value == "about:accountsettings") {
    tab.browser.contentDocument.documentElement.server = server;
    tab.browser.contentDocument.documentElement.selectPage = selectPage;
    tab.browser.contentWindow.onLoad();
    tabmail.switchToTab(tabInfo);
    return;

const contentFrame = document.getElementById("contentFrame");
contentFrame.addEventListener("load", () => {
  document
    .getElementById("accountTreeCreateAccount")
    .addEventListener("click", event => {
      document.getElementById("accountAddPopup").openPopup(event.target, {
        position: "after_start",
        triggerEvent: event,
      });
    });
  document
    .getElementById("accounttree")
    .addEventListener("contextmenu", event => {
      event.preventDefault();
    });
  const inputElements = contentFrame.contentDocument.querySelectorAll(
    "checkbox, input, menulist, radiogroup, richlistbox, select, textarea"
  );
  contentFrame.contentDocument.addEventListener("prefchange", () => {
    onAccept(true);
  });
  for (const input of inputElements) {
    if (["input", "select", "textarea"].includes(input.localName)) {
      input.addEventListener("change", () => {
        onAccept(true);
      });
    } else {
      input.addEventListener("command", () => {
        onAccept(true);
      });
